CREATE OR REPLACE FUNCTION public.analytics_record_signup_attribution(p_user uuid, p_attribution jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE k text; v text;
